-- Sedra Petrol: delete ALL business data (buildings, units, parties = customers / owners / suppliers / employees / drivers,
-- contracts, assets = meters / tanks / vehicles / equipment, invoices, payments, bills, journals, documents, logs ...).
-- Keeps setup: users/roles/permissions, company/branches, countries/cities, currencies, lookups, chart of accounts
-- (except the personal accounts of the deleted parties), account mappings, tax rates, fiscal periods, gas types,
-- checklist templates, Settings terms & conditions.
SET XACT_ABORT ON;
BEGIN TRANSACTION;

DELETE FROM dbo.[activity_log];
DELETE FROM dbo.[amc_payment_schedule];
DELETE FROM dbo.[amc_scope_item];
DELETE FROM dbo.[audit_trail_link];
DELETE FROM dbo.[bank_statement_line];
DELETE FROM dbo.[bank_transfer];
DELETE FROM dbo.[building_owner];
DELETE FROM dbo.[cashflow_item];
DELETE FROM dbo.[cd_renewal];
DELETE FROM dbo.[contract_fee];
DELETE FROM dbo.[contract_term] WHERE contract_id IS NOT NULL;
DELETE FROM dbo.[credit_note_allocation];
DELETE FROM dbo.[credit_note_line];
DELETE FROM dbo.[customer_refund_source];
DELETE FROM dbo.[document];
DELETE FROM dbo.[invoice_installment];
DELETE FROM dbo.[journal_approval];
DELETE FROM dbo.[meter_assignment];
DELETE FROM dbo.[meter_service];
DELETE FROM dbo.[meter_topup];
DELETE FROM dbo.[number_sequence];
DELETE FROM dbo.[party_bank_account];
DELETE FROM dbo.[party_contact];
DELETE FROM dbo.[payment_allocation];
DELETE FROM dbo.[refill_collection];
DELETE FROM dbo.[refill_po];
DELETE FROM dbo.[refill_purchase_invoice];
DELETE FROM dbo.[refill_schedule];
DELETE FROM dbo.[refill_stage_history];
DELETE FROM dbo.[refill_supplier_payment];
DELETE FROM dbo.[refresh_token];
DELETE FROM dbo.[tank_level_history];
DELETE FROM dbo.[vendor_bill_item];
DELETE FROM dbo.[vendor_payment_allocation];
DELETE FROM dbo.[visit_checklist_item];
DELETE FROM dbo.[visit_finding];
DELETE FROM dbo.[voucher];
DELETE FROM dbo.[audit_trail];
DELETE FROM dbo.[bank_reconciliation];
DELETE FROM dbo.[cd_certificate];
DELETE FROM dbo.[credit_note];
DELETE FROM dbo.[customer_refund];
DELETE FROM dbo.[invoice_item];
DELETE FROM dbo.[journal_line];
DELETE FROM dbo.[maintenance_visit];
DELETE FROM dbo.[payment];
DELETE FROM dbo.[service_request];
DELETE FROM dbo.[tank_refill];
DELETE FROM dbo.[vendor_bill];
DELETE FROM dbo.[vendor_payment];
DELETE FROM dbo.[asset_vehicle];
DELETE FROM dbo.[bank_account];
DELETE FROM dbo.[contract_amc_spec];
DELETE FROM dbo.[meter_reading];
DELETE FROM dbo.[refill_request];
DELETE FROM dbo.[vendor_contact];
DELETE FROM dbo.[asset_meter];
DELETE FROM dbo.[asset_tank];
DELETE FROM dbo.[contract_supply_spec];
DELETE FROM dbo.[driver];
DELETE FROM dbo.[invoice];
DELETE FROM dbo.[asset];
DELETE FROM dbo.[contract];
DELETE FROM dbo.[journal_entry];
DELETE FROM dbo.[party_customer];
DELETE FROM dbo.[party_vendor];
DELETE FROM dbo.[employee];
DELETE FROM dbo.[unit];
DELETE FROM dbo.[building];
DELETE FROM dbo.[party];

-- the personal ledger accounts of the deleted parties (customers 1202…, suppliers 2102…, employees 1203…)
DELETE a FROM dbo.account a JOIN dbo.account g ON g.id = a.parent_account_id
WHERE g.account_code IN (N'1202', N'2102', N'1203') AND a.is_group = 0;

-- restart the ids at 1 (only tables that were fully emptied)
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID(N'dbo.activity_log') AND last_value IS NOT NULL) DBCC CHECKIDENT (N'dbo.activity_log', RESEED, 0) WITH NO_INFOMSGS;
IF EXISTS (SELECT 1 FROM sys.identity_columns WHERE object_id = OBJECT_ID(N'dbo.amc_payment_schedule') AND last_value IS NOT NULL) DBCC CHECKIDENT (N'dbo.amc_payment_schedule', RESEED, 0) WITH NO_INFOMSGS;
